package com.example.studentmanagement.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity @Table(name="students") public class Student { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String name; @NotBlank @Email @Column(unique=true) private String email; @NotBlank private String course; @NotNull private Integer age; public Student(){} public Student(String n,String e,String c,Integer a){name=n;email=e;course=c;age=a;} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getCourse(){return course;} public void setCourse(String v){course=v;} public Integer getAge(){return age;} public void setAge(Integer v){age=v;} }
